    private AccessibilityNodeInfo node(AccessibilityNodeInfo n,String value){if(n==null)return null;if(value.contentEquals(n.getText()==null?"":n.getText())||value.contentEquals(n.getHintText()==null?"":n.getHintText()))return n;for(int index=0;index<n.getChildCount();index++){AccessibilityNodeInfo found=node(n.getChild(index),value);if(found!=null)return found;}return null;}
    private AccessibilityNodeInfo find(String value)throws Exception{long until=SystemClock.elapsedRealtime()+5000;AccessibilityNodeInfo found;do{found=node(i.getUiAutomation().getRootInActiveWindow(),value);if(found!=null)return found;Thread.sleep(80);}while(SystemClock.elapsedRealtime()<until);throw new AssertionError("UI control unavailable: "+value);}
