    private void click(String value)throws Exception{AccessibilityNodeInfo node=find(value);while(node!=null&&!node.isClickable())node=node.getParent();check.accept(node!=null&&node.performAction(AccessibilityNodeInfo.ACTION_CLICK),"UI action works: "+value);i.waitForIdleSync();}
